in H]         for k in range(6): bond(ids[k],ids[(k+1)%6])         # H correspond C1..C5         for k,h in enumerate(hids, start=1): bond(ids[k],h)         if donor_idx is not None and donor_bond: bond(donor_idx,ids[0])         return ids,hids      re=add('Re',(0,0,0),'core')     # ideal trigonal bipyramid     us=[norm((0,0,1)), norm((0.5,math.sqrt(3)/2,0)), norm((0.5,-math.sqrt(3)/2,0))]     for k,u in enumerate(us):         se=add('Se',u*L_ReSe,'core'); bond(re,se)         d=vec_around(u,78,params['sephi'][k])         ip=np.asarray(atoms[se][1])+L_SeC*d         add_phenyl(d,ip,params['seroll'][k],f'SePh{k+1}',se)     uP=norm((-1,0,0)); p=add('P',uP*L_ReP,'core'); bond(re,p)     for k in range(3):         # tetrahedral PPh3 fan; common azimuth base + 120         d=vec_around(uP,68,params['pbase']+120*k)         ip=np.asarray(atoms[p][1])+L_PC*d         add_phenyl(d,ip,params['proll'][k],f'PPh{k+1}',p)     uN=norm((0,0,-1)); n=add('N',uN*L_ReN,'core'); bond(re,n)     cn=np.asarray(atoms[n][1])+L_NC*uN; cni=add('C',cn,'MeCN'); bond(n,cni)     cm=cn+L_CC*uN; cmi=add('C',cm,'MeCN'); bond(cni,cmi)     e1,e2=perp_basis(uN)     for k in range(3):         a=math.radians(params['merot']+120*k)         radial=math.cos(a)*e1+math.sin(a)*e2         hd=norm(-0.333333333333*(-uN)+0.94280904158*radial)         h=add('H',cm+L_CH3*hd,'MeCN'); bond(cmi,h)     return atoms,conn  def score(atoms,conn, detail=False):     # Penalize close inter-group contacts; intragroup and directly bonded pairs ignored.     coords=np.array([a[1] for a in atoms]); els=[a[0] for a in atoms]; groups=[a[2] for a in atoms]     penalties=[]; minima={'HH':(99,None),'HC':(99,None),'heavy':(99,None)}     for i in range(len(atoms)):         for j in range(i+1,len(atoms)):             if groups[i]==groups[j] or (i,j) in conn: continue             d=float(np.linalg.norm(coords[i]-coords[j]))             ei,ej=els[i],els[j]             # threshold pair type; Re/P/Se fixed core interactions need less emphasis except very short             if ei=='H' and ej=='H': typ='HH'; target=1.65; soft=2.0             elif ei=='H' or ej=='H': typ='HC'; target=2.00; soft=2.35             else: typ='heavy'; target=2.55; soft=3.0             if d<minima[typ][0]: minima[typ]=(d,(i,j,ei,ej,groups[i],groups[j]))             if d<soft:                 # steep below target, gentler in soft region                 pen=(target-d)**2*10 if d<target else (soft-d)**2*0.25                 penalties.append((pen,d,i,j,ei,ej,groups[i],groups[j]))     val=sum(x[0] for x in penalties)     if detail:         return val,minima,sorted(penalties,reverse=True)     return val  def write_xyz(atoms,fn,comment):     with open(fn,'w') as f:         f.write(f'{len(atoms)}\n{comment}\n')         for el,c,g in atoms:             f.write(f'{el:2s} {c[0]: .8f} {c[1]: .8f} {c[2]: .8f}\n')  def random_params(rng):     return {         'sephi':[rng.uniform(0,360) for _ in range(3)],         'seroll':[rng.uniform(0,360) for _ in range(3)],         'pbase':rng.uniform(0,360),         'proll':[rng.uniform(0,360) for _ in range(3)],         'merot':rng.uniform(0,360),     }  if __name__=='__main__':     ap=argparse.ArgumentParser(); ap.add_argument('-n',type=int,default=20000); ap.add_argument('--seed',type=int,default=12345)     args=ap.parse_args(); rng=random.Random(args.seed)     best=None     # include hand-like starting point     candidates=[{'sephi':[15,205,155],'seroll':[25,-35,45],'pbase':20,'proll':[35,100,165],'merot':30}]     candidates += [random_params(rng) for _ in range(args.n)]     for it,prm in enumerate(candidates):         atoms,conn=build(prm)         val=score(atoms,conn)         if best is None or val<best[0]:             best=(val,it,prm,atoms,conn)             val2,mins,pens=score(atoms,conn,True)             print('new best',it,'score',val,'minima',mins,'params',prm,flush=True)     val,mins,pens=score(best[3],best[4],True)     print('BEST',best[0],best[1],best[2])     print('minima',mins)     print('top